//! The generator half of [the image module](../image.rs): [`emit`] writes a tier as a generated
//! file, [`check`] and [`check_texts`] recompute what a generated file writes as literals, and
//! [`compare_or_update`] is the golden test both images end in. Compiled for the lattice's tests
//! and under the `generator` feature, which koan's tests turn on: no shipped build carries it.

use std::collections::{BTreeMap, HashSet};
use std::fmt::Write;

use crate::bump::{Bump, FrozenTable};
use crate::symbols::{BinderSymbol, StaticText, StaticTexts, Symbol, SymbolInterner};

use super::super::component::Component;
use super::super::digest::{
    ComponentMember, TypeDigest, component_digest, node_digest, schema_content_digest,
};
use super::super::handle::FIXED;
use super::super::node::NodeSchema;
use super::super::schema::SigOrigin;
use super::super::shape::StoredElement;
use super::super::stored::{Content, Flags, Linked};
use super::super::tiers::Frozen;

/// The name of the `static` holding the node under `digest`: its fixed handle's name, or `N_` and
/// the digest in hexadecimal. The one naming rule, which koan's generator calls for its constants.
pub fn static_name(digest: TypeDigest) -> String {
    match FIXED.iter().find(|(_, fixed)| fixed.digest() == digest) {
        Some((name, _)) => name.to_string(),
        None => format!("N_{:032X}", digest.0),
    }
}

/// The source of a generated image holding `tier`'s own nodes, resting on what `tier` rests on:
/// the seed, or nothing. Every text the nodes name is read from `symbols`. `lattice` is the path
/// the file imports this module by, and `regenerate` the command its header names.
pub fn emit(
    tier: &Frozen<'_>,
    symbols: &SymbolInterner,
    lattice: &str,
    regenerate: &str,
) -> String {
    let below = tier.below();
    assert!(
        below.is_none_or(|below| below.below().is_none()),
        "an image rests on the seed or on nothing"
    );
    let mut nodes = Vec::new();
    tier.nodes().each(|node| nodes.push(node));
    nodes.sort_by_key(|node| node.digest());
    let mut emitter = Emitter {
        own: nodes.iter().map(|node| node.digest()).collect(),
        below,
        symbols,
        texts: BTreeMap::new(),
        components: BTreeMap::new(),
    };
    let mut body = String::new();
    for node in &nodes {
        let content = emitter.content(node.content());
        write!(
            body,
            "\npub static {}: StoredNode<'static> = StoredNode::imaged(\n    {},\n    {content},\n);\n",
            static_name(node.digest()),
            hex128(node.handle().bits()),
        )
        .expect("a String takes every write");
    }
    let mut components = String::new();
    for (digest, component) in std::mem::take(&mut emitter.components) {
        assert!(
            component_digest(component.members()) == digest,
            "the builtin image holds a recursive component: teach image::emit to write one"
        );
        let members: Vec<String> = component
            .members()
            .iter()
            .map(|member| emitter.member(member))
            .collect();
        write!(
            components,
            "\npub static C_{:032X}: Component<'static> = Component::imaged(\n    TypeDigest::imaged({}),\n    &[\n{}    ],\n);\n",
            digest.0,
            hex128(digest.0),
            members.iter().map(|member| format!("        {member},\n")).collect::<String>(),
        )
        .expect("a String takes every write");
    }

    let scratch = Bump::new();
    let mut out = format!("//! Generated by `{regenerate}`. Do not edit.\n\nuse {lattice}::*;\n");
    for (symbol, text) in &emitter.texts {
        write!(
            out,
            "\npub static S_{:032X}: StaticText = StaticText::imaged({}, {text:?});\n",
            symbol.0,
            hex128(symbol.0),
        )
        .expect("a String takes every write");
    }
    out.push_str(&components);
    out.push_str(&body);

    let placed = FrozenTable::placed(&scratch, nodes.len(), nodes.iter().copied());
    let slots: Vec<String> = placed
        .slots()
        .iter()
        .map(|slot| match slot.entry() {
            Some(node) => format!(
                "Slot::imaged({}, {})",
                hex64(slot.word()),
                emitter.node(node)
            ),
            None => "Slot::EMPTY".to_string(),
        })
        .collect();
    write_run(&mut out, "NODES", "StoredNode<'static>", &slots);
    let table = format!("FrozenTable::imaged(&NODES, {})", nodes.len());
    let image = match below {
        None => format!(
            "Frozen::imaged_root({table}, {}, {})",
            emitter.node(tier.never()),
            emitter.node(tier.any())
        ),
        Some(_) => format!("Frozen::imaged_over({table}, &seed::IMAGE)"),
    };
    write!(out, "\npub static IMAGE: Frozen<'static> = {image};\n")
        .expect("a String takes every write");

    if !emitter.texts.is_empty() {
        // A placement reads a text's symbol alone, so each is placed with an empty stand-in.
        let standins: Vec<StaticText> = emitter
            .texts
            .keys()
            .map(|symbol| StaticText::imaged(symbol.0, ""))
            .collect();
        let placed = FrozenTable::placed(&scratch, standins.len(), standins.iter());
        let slots: Vec<String> = placed
            .slots()
            .iter()
            .map(|slot| match slot.entry() {
                Some(text) => format!(
                    "Slot::imaged({}, &S_{:032X})",
                    hex64(slot.word()),
                    text.symbol().0
                ),
                None => "Slot::EMPTY".to_string(),
            })
            .collect();
        write_run(&mut out, "TEXTS", "StaticText", &slots);
        write!(
            out,
            "\npub static SYMBOLS: StaticTexts = StaticTexts::imaged(FrozenTable::imaged(&TEXTS, {}));\n",
            standins.len()
        )
        .expect("a String takes every write");
    }
    out
}

/// Write the `static` run `name` of `slots`, each of `entry`.
fn write_run(out: &mut String, name: &str, entry: &str, slots: &[String]) {
    write!(
        out,
        "\nstatic {name}: [Slot<'static, {entry}>; {}] = [\n",
        slots.len()
    )
    .expect("a String takes every write");
    for slot in slots {
        writeln!(out, "    {slot},").expect("a String takes every write");
    }
    out.push_str("];\n");
}

/// Fail unless the file at `path` reads `generated`, naming `regenerate`, the command that rewrites
/// it; with `UPDATE_IMAGE` set, write `generated` there instead. Each image's golden test ends here.
pub fn compare_or_update(path: &str, generated: &str, regenerate: &str) {
    if std::env::var_os("UPDATE_IMAGE").is_some() {
        std::fs::write(path, generated).unwrap_or_else(|error| panic!("writing {path}: {error}"));
        return;
    }
    let written = std::fs::read_to_string(path).unwrap_or_default();
    assert!(written == generated, "{path} is stale: run `{regenerate}`");
}

/// Every mismatch between `tier`'s own static content and what it was generated from: a node whose
/// digest is not its content's, whose concrete flag is not its content's, or a signature's schema
/// digest or a component's digest that is not its content's. Empty when the image is sound.
pub fn check(tier: &Frozen<'_>) -> Vec<String> {
    let scratch = Bump::new();
    let mut found = Vec::new();
    tier.nodes().each(|node| {
        let name = static_name(node.digest());
        let computed = node_digest(&scratch, &node.view());
        if computed != node.digest() {
            found.push(format!("{name}: its content digests to {computed:#034x}"));
        }
        if node.handle().is_concrete() != node.is_concrete() {
            found.push(format!("{name}: its concrete flag is not its content's"));
        }
        match node.content() {
            Content::Signature {
                schema,
                schema_digest,
            } if schema_content_digest(*schema) != schema_digest => {
                found.push(format!("{name}: its schema digest is not its schema's"));
            }
            Content::SetMember { component, .. }
                if component_digest(component.members()) != component.digest =>
            {
                found.push(format!(
                    "{name}: its component's digest is not its members'"
                ));
            }
            _ => {}
        }
    });
    found
}

/// Every text of `texts` whose symbol is not its text's digest.
pub fn check_texts(texts: &StaticTexts) -> Vec<String> {
    let mut found = Vec::new();
    texts.each(|text| {
        if Symbol::of(text.text()) != text.symbol() {
            found.push(format!("{:?}: its symbol is not its digest", text.text()));
        }
    });
    found
}

/// The state [`emit`] writes through: which nodes are the tier's own, the tier it rests on, and the
/// texts and components the written nodes name, gathered as they are written.
struct Emitter<'a, 'g> {
    own: HashSet<TypeDigest>,
    below: Option<&'g Frozen<'g>>,
    symbols: &'a SymbolInterner,
    texts: BTreeMap<Symbol, String>,
    components: BTreeMap<TypeDigest, &'g Component<'g>>,
}

impl<'g> Emitter<'_, 'g> {
    /// A reference to the static holding the node under `digest`: the tier's own, or a named seed
    /// node.
    fn named(&self, digest: TypeDigest) -> String {
        if self.own.contains(&digest) {
            return format!("&{}", static_name(digest));
        }
        let below = self
            .below
            .unwrap_or_else(|| panic!("{digest:#034x} lies in no tier of the image"));
        assert!(
            below.find(digest).is_some(),
            "{digest:#034x} lies in no tier of the image"
        );
        assert!(
            FIXED.iter().any(|(_, fixed)| fixed.digest() == digest),
            "the seed node {digest:#034x} has no fixed name"
        );
        format!("&seed::{}", static_name(digest))
    }

    fn node(&self, node: Linked<'_>) -> String {
        self.named(node.digest())
    }

    /// A reference to the static holding `symbol`'s text, which `symbols` must record.
    fn text(&mut self, symbol: Symbol) -> String {
        let text = self.symbols.resolve(symbol).unwrap_or_else(|| {
            panic!(
                "the image names symbol {:#034x}, whose text was never recorded",
                symbol.0
            )
        });
        self.texts.insert(symbol, text);
        format!("&S_{:032X}", symbol.0)
    }

    fn binder(&mut self, binder: BinderSymbol) -> String {
        match binder {
            BinderSymbol::Value(name) => {
                format!(
                    "BinderSymbol::Value(ValueSymbol::imaged({}))",
                    self.text(name.symbol())
                )
            }
            BinderSymbol::Type(name) => {
                format!(
                    "BinderSymbol::Type(TypeSymbol::imaged({}))",
                    self.text(name.symbol())
                )
            }
            BinderSymbol::Registration(_) | BinderSymbol::Key(_) => {
                panic!("the builtin image names no textless binder: teach image::emit to write one")
            }
        }
    }

    fn member(&mut self, member: &ComponentMember<'_>) -> String {
        let schema = match member.schema {
            NodeSchema::NewType(representation) => {
                format!(
                    "NodeSchema::NewType(KType::imaged({}))",
                    self.named(representation.digest())
                )
            }
            NodeSchema::TypeConstructor {
                representation,
                param_names,
            } => {
                let representation = match representation {
                    Some(representation) => format!(
                        "Some(Parametric::imaged({}))",
                        self.named(representation.digest())
                    ),
                    None => "None".to_string(),
                };
                let names: Vec<String> = param_names
                    .iter()
                    .map(|name| format!("TypeSymbol::imaged({})", self.text(name.symbol())))
                    .collect();
                format!(
                    "NodeSchema::TypeConstructor {{ representation: {representation}, param_names: &[{}] }}",
                    names.join(", ")
                )
            }
        };
        format!(
            "ComponentMember {{ name: TypeSymbol::imaged({}), kind: KKind::{:?}, schema: {schema} }}",
            self.text(member.name.symbol()),
            member.kind
        )
    }

    /// `content` as a generated file spells it: **the emit table**, one exhaustive match. A variant
    /// no builtin image holds panics, naming itself.
    fn content(&mut self, content: Content<'g>) -> String {
        let flags = |flags: Flags| format!("Flags::imaged({:#04x})", flags.bits());
        let unwritten = |variant: &str| -> ! {
            panic!("the builtin image holds no {variant}: teach image::emit to write one")
        };
        match content {
            Content::Number => "Content::Number".into(),
            Content::Str => "Content::Str".into(),
            Content::Bool => "Content::Bool".into(),
            Content::Null => "Content::Null".into(),
            Content::Identifier => "Content::Identifier".into(),
            Content::Symbol => "Content::Symbol".into(),
            Content::TypeNameToken => "Content::TypeNameToken".into(),
            Content::Expression => "Content::Expression".into(),
            Content::SigiledTypeExpr => "Content::SigiledTypeExpr".into(),
            Content::RecordType => "Content::RecordType".into(),
            Content::Literal => "Content::Literal".into(),
            Content::Block => "Content::Block".into(),
            Content::Declaration => "Content::Declaration".into(),
            Content::Binder => "Content::Binder".into(),
            Content::Name => "Content::Name".into(),
            Content::Keyword => "Content::Keyword".into(),
            Content::Any => "Content::Any".into(),
            Content::AnyValue => "Content::AnyValue".into(),
            Content::AnyCode => "Content::AnyCode".into(),
            Content::Never => "Content::Never".into(),
            Content::OfKind(kind) => format!("Content::OfKind(KKind::{kind:?})"),
            Content::List {
                flags: bits,
                element,
            } => format!(
                "Content::List {{ flags: {}, element: {} }}",
                flags(bits),
                self.node(element)
            ),
            Content::Dict {
                flags: bits,
                key,
                value,
            } => format!(
                "Content::Dict {{ flags: {}, key: {}, value: {} }}",
                flags(bits),
                self.node(key),
                self.node(value)
            ),
            Content::Record {
                flags: bits,
                fields,
            } => {
                let fields: Vec<String> = fields
                    .raw()
                    .iter()
                    .map(|(name, field)| format!("({}, {})", self.binder(*name), self.node(field)))
                    .collect();
                format!(
                    "Content::Record {{ flags: {}, fields: Record::imaged(&[{}]) }}",
                    flags(bits),
                    fields.join(", ")
                )
            }
            Content::ExpressionShape {
                flags: bits,
                elements,
                ret,
            } => {
                let elements: Vec<String> = elements
                    .raw()
                    .iter()
                    .map(|element| match *element {
                        StoredElement::Keyword(keyword) => format!(
                            "StoredElement::Keyword(KeywordSymbol::imaged({}))",
                            self.text(keyword.symbol())
                        ),
                        StoredElement::Slot(slot, class) => {
                            format!("StoredElement::Slot({}, {class})", self.node(slot))
                        }
                    })
                    .collect();
                format!(
                    "Content::ExpressionShape {{ flags: {}, elements: Elements::imaged(&[{}]), ret: {} }}",
                    flags(bits),
                    elements.join(", "),
                    self.node(ret)
                )
            }
            Content::Quantified { index, bound } => format!(
                "Content::Quantified {{ index: {index}, bound: {} }}",
                self.node(bound)
            ),
            Content::Union {
                flags: bits,
                members,
            } => {
                let members: Vec<String> = members
                    .raw()
                    .iter()
                    .map(|member| self.node(member))
                    .collect();
                format!(
                    "Content::Union {{ flags: {}, members: Run::imaged(&[{}]) }}",
                    flags(bits),
                    members.join(", ")
                )
            }
            Content::Signature {
                schema,
                schema_digest,
            } => {
                assert!(
                    schema.is_empty() && schema.origin == SigOrigin::Module,
                    "the builtin image holds no signature but the empty one: teach image::emit \
                     to write one"
                );
                format!(
                    "Content::Signature {{ schema: &SigSchema::EMPTY, schema_digest: TypeDigest::imaged({}) }}",
                    hex128(schema_digest.0)
                )
            }
            Content::SetMember {
                kind,
                index,
                component,
                name,
            } => {
                self.components.insert(component.digest, component);
                format!(
                    "Content::SetMember {{ kind: KKind::{kind:?}, index: {index}, component: &C_{:032X}, name: TypeSymbol::imaged({}) }}",
                    component.digest.0,
                    self.text(name.symbol())
                )
            }
            Content::CodeNeeding { .. } => unwritten("CodeNeeding"),
            Content::CodeUnbuilt { .. } => unwritten("CodeUnbuilt"),
            Content::Parameter { .. } => unwritten("Parameter"),
            Content::Carrier { .. } => unwritten("Carrier"),
            Content::KFunction { .. } => unwritten("KFunction"),
            Content::Scheme { .. } => unwritten("Scheme"),
            Content::Lexical { .. } => unwritten("Lexical"),
            Content::ConstructorApply { .. } => unwritten("ConstructorApply"),
            Content::SignatureApply { .. } => unwritten("SignatureApply"),
            Content::SignatureMeet { .. } => unwritten("SignatureMeet"),
            Content::DeferredReturn(_) => unwritten("DeferredReturn"),
            Content::Sibling(_) => unwritten("Sibling"),
        }
    }
}

/// `bits` as a generated file writes a 128-bit word: 32 hexadecimal digits in groups of eight.
fn hex128(bits: u128) -> String {
    let digits = format!("{bits:032x}");
    format!(
        "0x{}_{}_{}_{}",
        &digits[..8],
        &digits[8..16],
        &digits[16..24],
        &digits[24..]
    )
}

/// `bits` as a generated file writes a 64-bit word: 16 hexadecimal digits in groups of eight.
fn hex64(bits: u64) -> String {
    let digits = format!("{bits:016x}");
    format!("0x{}_{}", &digits[..8], &digits[8..])
}
